SELECT * FROM (SELECT 'bp' AS t, b.mention_notice_id AS a, b.mention_section_id AS b, b.tender_id AS c, m.name AS d, b.seq = t.current_seq AS e FROM tender_version_bid_parties b CROSS JOIN organization_mentions m ON m.notice_id = b.mention_notice_id AND m.section_id = b.mention_section_id CROSS JOIN tenders t ON t.id = b.tender_id WHERE b.organization_id = 36 LIMIT 400) UNION ALL SELECT 'bpc' AS t, count(*) AS a, count(DISTINCT mention_notice_id) AS b, count(DISTINCT tender_id) AS c, NULL AS d, NULL AS e FROM tender_version_bid_parties WHERE organization_id = 36 UNION ALL SELECT 'wc' AS t, count(*) AS a, count(DISTINCT tender_id) AS b, NULL AS c, NULL AS d, NULL AS e FROM tender_version_result_winners WHERE organization_id = 36 UNION ALL SELECT * FROM (SELECT 'nm' AS t, count(*) AS a, min(notice_id) AS b, max(notice_id) AS c, name AS d, NULL AS e FROM (SELECT name, notice_id FROM organization_mentions WHERE organization_id = 36 ORDER BY rowid DESC LIMIT 6000) GROUP BY name ORDER BY 2 DESC LIMIT 150)
